-- Publicación atómica del grupo Crema de camarones (7 idiomas) — 2026-10-07
-- Requisito previo: PR de Crema de camarones desplegado (imágenes /recetas/crema-de-camarones/* respondiendo 200).
do $pub$
declare
  g constant uuid := '2b9ed02a-dbdc-4ad6-989e-428323d1bf14';
  es_id constant uuid := '6bc5c2a0-f55c-48b3-b974-a441f3ce8b71';
  j constant jsonb := $j$[
{"id":"6bc5c2a0-f55c-48b3-b974-a441f3ce8b71","recipe_group_id":"2b9ed02a-dbdc-4ad6-989e-428323d1bf14","language":"es","slug":"receta-crema-de-camarones","public_path":"/receta-crema-de-camarones","source_url":null,"title":"Crema de camarones","excerpt":"Crema de camarones con verduras, papa y crema de leche, coronada con camarones salteados. Para 4 personas, lista en 45 minutos.","summary":"La crema de camarones se prepara sofriendo cebolla, ajo y zanahoria en mantequilla, cociendo la papa en caldo con un poco de pasta de tomate, añadiendo camarones y triturando todo hasta obtener una crema lisa que se termina con crema de leche. Se sirve con camarones salteados por encima.\n\nLa receta tarda 45 minutos entre preparación y cocción. Rinde 4 porciones.","category":"Sopas y cremas","difficulty":"Media","course":"Entrante","cuisine":"Latinoamericana","prep_time_minutes":15,"cook_time_minutes":30,"total_time_minutes":45,"servings":4,"keywords":["crema de camarones","receta de crema de camarones","cómo hacer crema de camarones","crema de camarones con papa","sopa cremosa de camarones","crema de mariscos fácil","crema de camarones con crema de leche"],"ingredients":[{"name":"camarones pelados","amount":"300","unit":"g","group":"Para la crema"},{"name":"cebolla","amount":"1","unit":"","group":"Para la crema"},{"name":"dientes de ajo","amount":"2","unit":"","group":"Para la crema"},{"name":"zanahoria","amount":"1","unit":"","group":"Para la crema"},{"name":"papa","amount":"1","unit":"","group":"Para la crema"},{"name":"mantequilla","amount":"30","unit":"g","group":"Para la crema"},{"name":"pasta de tomate","amount":"1","unit":"cucharada","group":"Para la crema"},{"name":"caldo de pollo o de pescado","amount":"800","unit":"ml","group":"Para la crema"},{"name":"crema de leche","amount":"100","unit":"ml","group":"Para la crema"},{"name":"sal","amount":"1","unit":"pizca","group":"Para la crema"},{"name":"pimienta negra molida","amount":"1","unit":"pizca","group":"Para la crema"},{"name":"camarones pelados, para saltear","amount":"200","unit":"g","group":"Para los camarones salteados"},{"name":"aceite de oliva","amount":"1","unit":"cucharada","group":"Para los camarones salteados"},{"name":"perejil picado","amount":"1","unit":"cucharada","group":"Para servir"},{"name":"crema de leche, para decorar","amount":"1","unit":"cucharada","group":"Para servir"}],"steps":[{"title":"Prepara los ingredientes","content":"Pica 1 cebolla y 2 dientes de ajo, corta en rodajas 1 zanahoria y en cubos 1 papa pelada. Separa los camarones pelados: 300 g para la crema y 200 g para saltear al final.","image_url":"/recetas/crema-de-camarones/paso-01.webp","image_alt":"Crema de camarones: Prepara los ingredientes"},{"title":"Sofríe las verduras","content":"Derrite 30 g de mantequilla en una olla a fuego medio y sofríe la cebolla, el ajo y la zanahoria 5 minutos, hasta que estén blandos.","image_url":"/recetas/crema-de-camarones/paso-02.webp","image_alt":"Crema de camarones: Sofríe las verduras"},{"title":"Cuece la papa","content":"Añade la papa, 1 cucharada de pasta de tomate y 800 ml de caldo. Cuece 15 minutos a fuego medio, hasta que la papa esté tierna.","image_url":"/recetas/crema-de-camarones/paso-03.webp","image_alt":"Crema de camarones: Cuece la papa"},{"title":"Añade los camarones","content":"Incorpora 300 g de camarones y cuece 3 minutos, hasta que estén rosados.","image_url":"/recetas/crema-de-camarones/paso-04.webp","image_alt":"Crema de camarones: Añade los camarones"},{"title":"Tritura","content":"Retira la olla del fuego y tritura con batidora de mano hasta obtener una crema lisa.","image_url":"/recetas/crema-de-camarones/paso-05.webp","image_alt":"Crema de camarones: Tritura"},{"title":"Añade la crema de leche","content":"Vuelve a poner la olla a fuego bajo, añade 100 ml de crema de leche y calienta 2 minutos, sin dejar que hierva.","image_url":"/recetas/crema-de-camarones/paso-06.webp","image_alt":"Crema de camarones: Añade la crema de leche"},{"title":"Rectifica la sazón","content":"Prueba y rectifica con 1 pizca de sal y 1 pizca de pimienta.","image_url":"/recetas/crema-de-camarones/paso-07.webp","image_alt":"Crema de camarones: Rectifica la sazón"},{"title":"Saltea y sirve","content":"Saltea los 200 g de camarones restantes 2 minutos con 1 cucharada de aceite. Sirve la crema en platos hondos, reparte los camarones salteados por encima, espolvorea perejil y termina con un hilo de crema de leche.","image_url":"/recetas/crema-de-camarones/paso-08.webp","image_alt":"Crema de camarones: Saltea y sirve"}],"image_url":"/recetas/crema-de-camarones/portada.webp","gallery":[{"url":"/recetas/crema-de-camarones/portada.webp","alt":"Crema de camarones"}],"notes":"Tritura con cuidado: el líquido caliente salpica, así que no llenes el vaso de la batidora más de la mitad si usas una de vaso. Si la crema te queda muy espesa, aclárala con un poco más de caldo caliente. No dejes que hierva al añadir la crema de leche, o puede cortarse. Los camarones solo necesitan unos minutos: pasarse los deja gomosos. Se conserva hasta 2 días en la nevera; recaliéntala a fuego bajo, sin hervir, y saltea los camarones frescos al momento.","nutrition":{"calories":360,"protein_g":29.0,"carbs_g":16,"fat_g":20.9,"sodium_mg":912,"serving_size":"1 porción (1/4 de la receta)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Suma de nutrientes por 100 g multiplicados por los pesos de los ingredientes y divididos entre 4 porciones. Se usan 500 g de camarones crudos pelados, 110 g de cebolla, 6 g de ajo, 80 g de zanahoria, 200 g de papa, 30 g de mantequilla, 16 g de pasta de tomate, 800 g de caldo, 114 g de crema de leche, 13,5 g de aceite de oliva y 4 g de perejil. La sal y la pimienta no se cuentan.","note":"Estimación por porción. El caldo se calcula como caldo de pollo listo para tomar, y el valor de sodio varía mucho según la marca. Se cuenta toda la mantequilla y todo el aceite aunque parte quede en la olla o la sartén.","inputs":[{"fdc_id":"175180","description":"Crustaceans, shrimp, mixed species, raw (500 g de camarones pelados)","grams":500,"per100":{"calories":85,"protein_g":20.1,"carbs_g":0.2,"fat_g":0.51,"saturated_fat_g":0.145,"fiber_g":0,"sodium_mg":119}},{"fdc_id":"170000","description":"Onions, raw (1 cebolla ≈ 110 g)","grams":110,"per100":{"calories":40,"protein_g":1.1,"carbs_g":9.34,"fat_g":0.1,"saturated_fat_g":0.042,"fiber_g":1.7,"sodium_mg":4}},{"fdc_id":"169230","description":"Garlic, raw (2 dientes ≈ 6 g)","grams":6,"per100":{"calories":149,"protein_g":6.36,"carbs_g":33.06,"fat_g":0.5,"saturated_fat_g":0.089,"fiber_g":2.1,"sodium_mg":17}},{"fdc_id":"170393","description":"Carrots, raw (1 zanahoria ≈ 80 g)","grams":80,"per100":{"calories":41,"protein_g":0.93,"carbs_g":9.58,"fat_g":0.24,"saturated_fat_g":0.037,"fiber_g":2.8,"sodium_mg":69}},{"fdc_id":"170026","description":"Potatoes, flesh and skin, raw (1 papa ≈ 200 g)","grams":200,"per100":{"calories":77,"protein_g":2.05,"carbs_g":17.49,"fat_g":0.09,"saturated_fat_g":0.026,"fiber_g":2.1,"sodium_mg":6}},{"fdc_id":"173430","description":"Butter, salted (30 g)","grams":30,"per100":{"calories":717,"protein_g":0.85,"carbs_g":0.06,"fat_g":81.11,"saturated_fat_g":51.368,"fiber_g":0,"sodium_mg":643}},{"fdc_id":"170459","description":"Tomato products, canned, paste, without salt added (1 cucharada ≈ 16 g)","grams":16,"per100":{"calories":82,"protein_g":4.32,"carbs_g":18.91,"fat_g":0.47,"saturated_fat_g":0.067,"fiber_g":4.1,"sodium_mg":59}},{"fdc_id":"172884","description":"Soup, chicken broth, ready-to-serve (800 ml ≈ 800 g)","grams":800,"per100":{"calories":5,"protein_g":0.6,"carbs_g":0.1,"fat_g":0.2,"saturated_fat_g":0.05,"fiber_g":0,"sodium_mg":343}},{"fdc_id":"170859","description":"Cream, fluid, heavy whipping (100 ml + 1 cucharada ≈ 114 g)","grams":114,"per100":{"calories":340,"protein_g":2.84,"carbs_g":2.76,"fat_g":36.08,"saturated_fat_g":22.759,"fiber_g":0,"sodium_mg":27}},{"fdc_id":"171413","description":"Oil, olive, salad or cooking (1 cucharada ≈ 13,5 g)","grams":13.5,"per100":{"calories":884,"protein_g":0,"carbs_g":0,"fat_g":100,"saturated_fat_g":13.81,"fiber_g":0,"sodium_mg":2}},{"fdc_id":"170416","description":"Parsley, fresh (1 cucharada ≈ 4 g)","grams":4,"per100":{"calories":36,"protein_g":2.97,"carbs_g":6.33,"fat_g":0.79,"saturated_fat_g":0.132,"fiber_g":3.3,"sodium_mg":56}}]},"seo":{"title":"Crema de camarones cremosa y fácil | Manual de Cocina","description":"Crema de camarones con papa, zanahoria y crema de leche, coronada con camarones salteados. Para 4 personas, lista en 45 minutos. Receta paso a paso.","image_variants":["/recetas/crema-de-camarones/portada-1x1.webp","/recetas/crema-de-camarones/portada-4x3.webp","/recetas/crema-de-camarones/portada-16x9.webp"],"faq":[{"q":"¿Se puede hacer la crema de camarones sin crema de leche?","a":"Sí. Quedará más ligera: puedes dejarla solo con la papa triturada, que ya le da cuerpo, o sustituir la crema de leche por leche evaporada."},{"q":"¿Se pueden usar camarones congelados?","a":"Sí. Descongélalos en la nevera, escúrrelos y sécalos con papel de cocina antes de añadirlos o saltearlos."},{"q":"¿Cómo evito que la crema de camarones se corte?","a":"Añade la crema de leche con el fuego bajo y no dejes que hierva después de incorporarla; solo caliéntala 2 minutos."}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"b95eda77-aa98-5d57-83d2-70c5fd0480aa","recipe_group_id":"2b9ed02a-dbdc-4ad6-989e-428323d1bf14","language":"de","slug":"garnelencremesuppe","public_path":"/de/garnelencremesuppe","source_url":null,"title":"Garnelencremesuppe","excerpt":"Cremige Garnelensuppe mit Gemüse, Kartoffel und Sahne, mit gebratenen Garnelen obenauf. Für 4 Personen, fertig in 45 Minuten.","summary":"Für die Garnelencremesuppe werden Zwiebel, Knoblauch und Karotte in Butter angeschwitzt, die Kartoffel mit etwas Tomatenmark in Brühe gegart, Garnelen zugegeben und alles zu einer glatten Suppe püriert, die mit Sahne abgeschlossen wird. Serviert wird sie mit gebratenen Garnelen obenauf.\n\nDas Rezept dauert 45 Minuten für Vorbereitung und Garen. Ergibt 4 Portionen.","category":"Suppen und Cremesuppen","difficulty":"Mittel","course":"Vorspeise","cuisine":"Lateinamerikanisch","prep_time_minutes":15,"cook_time_minutes":30,"total_time_minutes":45,"servings":4,"keywords":["Garnelencremesuppe","Garnelencremesuppe Rezept","Garnelensuppe selber machen","Garnelensuppe mit Kartoffeln","cremige Garnelensuppe","Meeresfrüchtesuppe einfach","crema de camarones"],"ingredients":[{"name":"geschälte Garnelen","amount":"300","unit":"g","group":"Für die Suppe"},{"name":"Zwiebel","amount":"1","unit":"","group":"Für die Suppe"},{"name":"Knoblauchzehen","amount":"2","unit":"","group":"Für die Suppe"},{"name":"Karotte","amount":"1","unit":"","group":"Für die Suppe"},{"name":"Kartoffel","amount":"1","unit":"","group":"Für die Suppe"},{"name":"Butter","amount":"30","unit":"g","group":"Für die Suppe"},{"name":"Tomatenmark","amount":"1","unit":"Esslöffel","group":"Für die Suppe"},{"name":"Hühner- oder Fischbrühe","amount":"800","unit":"ml","group":"Für die Suppe"},{"name":"Sahne","amount":"100","unit":"ml","group":"Für die Suppe"},{"name":"Salz","amount":"1","unit":"Prise","group":"Für die Suppe"},{"name":"schwarzer Pfeffer, gemahlen","amount":"1","unit":"Prise","group":"Für die Suppe"},{"name":"geschälte Garnelen, zum Braten","amount":"200","unit":"g","group":"Für die gebratenen Garnelen"},{"name":"Olivenöl","amount":"1","unit":"Esslöffel","group":"Für die gebratenen Garnelen"},{"name":"gehackte Petersilie","amount":"1","unit":"Esslöffel","group":"Zum Servieren"},{"name":"Sahne, zum Garnieren","amount":"1","unit":"Esslöffel","group":"Zum Servieren"}],"steps":[{"title":"Zutaten vorbereiten","content":"1 Zwiebel und 2 Knoblauchzehen hacken, 1 Karotte in Scheiben und 1 geschälte Kartoffel in Würfel schneiden. Die geschälten Garnelen aufteilen: 300 g für die Suppe und 200 g zum Braten am Schluss.","image_url":"/recetas/crema-de-camarones/paso-01.webp","image_alt":"Garnelencremesuppe: Zutaten vorbereiten"},{"title":"Gemüse anschwitzen","content":"30 g Butter in einem Topf bei mittlerer Hitze schmelzen und Zwiebel, Knoblauch und Karotte 5 Minuten anschwitzen, bis sie weich sind.","image_url":"/recetas/crema-de-camarones/paso-02.webp","image_alt":"Garnelencremesuppe: Gemüse anschwitzen"},{"title":"Kartoffel garen","content":"Kartoffel, 1 Esslöffel Tomatenmark und 800 ml Brühe zugeben. Bei mittlerer Hitze 15 Minuten garen, bis die Kartoffel weich ist.","image_url":"/recetas/crema-de-camarones/paso-03.webp","image_alt":"Garnelencremesuppe: Kartoffel garen"},{"title":"Garnelen zugeben","content":"300 g Garnelen zugeben und 3 Minuten garen, bis sie rosa sind.","image_url":"/recetas/crema-de-camarones/paso-04.webp","image_alt":"Garnelencremesuppe: Garnelen zugeben"},{"title":"Pürieren","content":"Den Topf vom Herd nehmen und mit dem Stabmixer zu einer glatten Suppe pürieren.","image_url":"/recetas/crema-de-camarones/paso-05.webp","image_alt":"Garnelencremesuppe: Pürieren"},{"title":"Sahne zugeben","content":"Den Topf wieder bei niedriger Hitze aufsetzen, 100 ml Sahne zugeben und 2 Minuten erhitzen, ohne dass sie kocht.","image_url":"/recetas/crema-de-camarones/paso-06.webp","image_alt":"Garnelencremesuppe: Sahne zugeben"},{"title":"Abschmecken","content":"Mit 1 Prise Salz und 1 Prise Pfeffer abschmecken.","image_url":"/recetas/crema-de-camarones/paso-07.webp","image_alt":"Garnelencremesuppe: Abschmecken"},{"title":"Braten und servieren","content":"Die restlichen 200 g Garnelen 2 Minuten in 1 Esslöffel Öl anbraten. Die Suppe in tiefe Teller füllen, die gebratenen Garnelen darauf verteilen, mit Petersilie bestreuen und mit einem Faden Sahne abschließen.","image_url":"/recetas/crema-de-camarones/paso-08.webp","image_alt":"Garnelencremesuppe: Braten und servieren"}],"image_url":"/recetas/crema-de-camarones/portada.webp","gallery":[{"url":"/recetas/crema-de-camarones/portada.webp","alt":"Garnelencremesuppe"}],"notes":"Vorsichtig pürieren: Heiße Flüssigkeit spritzt, deshalb den Mixbecher bei einem Standmixer höchstens halb füllen. Ist die Suppe zu dick, mit etwas heißer Brühe verdünnen. Nach dem Zugeben der Sahne nicht mehr kochen, sonst kann sie ausflocken. Die Garnelen brauchen nur wenige Minuten, zu langes Garen macht sie zäh. Hält sich bis zu 2 Tage im Kühlschrank; bei niedriger Hitze erwärmen, ohne zu kochen, und die Garnelen frisch braten.","nutrition":{"calories":360,"protein_g":29.0,"carbs_g":16,"fat_g":20.9,"sodium_mg":912,"serving_size":"1 Portion (1/4 des Rezepts)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Nährwerte je 100 g, multipliziert mit dem Gewicht der Zutaten und durch 4 Portionen geteilt. Verwendet werden 500 g rohe geschälte Garnelen, 110 g Zwiebel, 6 g Knoblauch, 80 g Karotte, 200 g Kartoffel, 30 g Butter, 16 g Tomatenmark, 800 g Brühe, 114 g Sahne, 13,5 g Olivenöl und 4 g Petersilie. Salz und Pfeffer werden nicht gezählt.","note":"Schätzung pro Portion. Die Brühe wird als trinkfertige Hühnerbrühe berechnet, der Natriumwert schwankt je nach Marke stark. Die gesamte Butter und das gesamte Öl werden gezählt, auch wenn ein Teil im Topf oder in der Pfanne bleibt."},"seo":{"title":"Garnelencremesuppe, cremig und einfach | Manual de Cocina","description":"Garnelencremesuppe mit Kartoffel, Karotte und Sahne, mit gebratenen Garnelen obenauf. Für 4 Personen, fertig in 45 Minuten. Rezept Schritt für Schritt.","image_variants":["/recetas/crema-de-camarones/portada-1x1.webp","/recetas/crema-de-camarones/portada-4x3.webp","/recetas/crema-de-camarones/portada-16x9.webp"],"faq":[{"q":"Kann man die Garnelensuppe ohne Sahne machen?","a":"Ja. Sie wird leichter: Die pürierte Kartoffel gibt schon Bindung, oder die Sahne wird durch Kondensmilch ersetzt."},{"q":"Kann man tiefgekühlte Garnelen verwenden?","a":"Ja. Im Kühlschrank auftauen, abtropfen lassen und mit Küchenpapier trocken tupfen, bevor sie in die Suppe kommen oder gebraten werden."},{"q":"Wie verhindere ich, dass die Suppe ausflockt?","a":"Die Sahne bei niedriger Hitze zugeben und danach nicht mehr kochen lassen, nur 2 Minuten erhitzen."}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"740f163c-c66f-5dba-8f7e-3598eeeb41f6","recipe_group_id":"2b9ed02a-dbdc-4ad6-989e-428323d1bf14","language":"en","slug":"creamy-shrimp-soup","public_path":"/en/creamy-shrimp-soup","source_url":null,"title":"Creamy Shrimp Soup","excerpt":"Creamy shrimp soup with vegetables, potato and cream, topped with sautéed shrimp. Serves 4, ready in 45 minutes.","summary":"Creamy shrimp soup is made by softening onion, garlic and carrot in butter, simmering potato in stock with a little tomato paste, adding shrimp and blending everything smooth, then finishing with cream. It is served topped with sautéed shrimp.\n\nThe recipe takes 45 minutes from prep to table. It serves 4.","category":"Soups & creams","difficulty":"Medium","course":"Starter","cuisine":"Latin American","prep_time_minutes":15,"cook_time_minutes":30,"total_time_minutes":45,"servings":4,"keywords":["creamy shrimp soup","shrimp soup recipe","how to make shrimp soup","shrimp bisque style soup","shrimp and potato soup","easy seafood soup","crema de camarones"],"ingredients":[{"name":"peeled raw shrimp","amount":"300","unit":"g","group":"For the soup"},{"name":"onion","amount":"1","unit":"","group":"For the soup"},{"name":"garlic cloves","amount":"2","unit":"","group":"For the soup"},{"name":"carrot","amount":"1","unit":"","group":"For the soup"},{"name":"potato","amount":"1","unit":"","group":"For the soup"},{"name":"butter","amount":"30","unit":"g","group":"For the soup"},{"name":"tomato paste","amount":"1","unit":"tablespoon","group":"For the soup"},{"name":"chicken or fish stock","amount":"800","unit":"ml","group":"For the soup"},{"name":"cream","amount":"100","unit":"ml","group":"For the soup"},{"name":"salt","amount":"1","unit":"pinch","group":"For the soup"},{"name":"ground black pepper","amount":"1","unit":"pinch","group":"For the soup"},{"name":"peeled raw shrimp, for sautéing","amount":"200","unit":"g","group":"For the sautéed shrimp"},{"name":"olive oil","amount":"1","unit":"tablespoon","group":"For the sautéed shrimp"},{"name":"chopped parsley","amount":"1","unit":"tablespoon","group":"To serve"},{"name":"cream, to drizzle","amount":"1","unit":"tablespoon","group":"To serve"}],"steps":[{"title":"Prepare the ingredients","content":"Chop 1 onion and 2 garlic cloves, slice 1 carrot and dice 1 peeled potato. Divide the peeled shrimp: 300 g for the soup and 200 g to sauté at the end.","image_url":"/recetas/crema-de-camarones/paso-01.webp","image_alt":"Creamy Shrimp Soup: Prepare the ingredients"},{"title":"Soften the vegetables","content":"Melt 30 g butter in a pot over medium heat and cook the onion, garlic and carrot for 5 minutes, until soft.","image_url":"/recetas/crema-de-camarones/paso-02.webp","image_alt":"Creamy Shrimp Soup: Soften the vegetables"},{"title":"Cook the potato","content":"Add the potato, 1 tablespoon tomato paste and 800 ml stock. Simmer over medium heat for 15 minutes, until the potato is tender.","image_url":"/recetas/crema-de-camarones/paso-03.webp","image_alt":"Creamy Shrimp Soup: Cook the potato"},{"title":"Add the shrimp","content":"Add 300 g shrimp and cook for 3 minutes, until pink.","image_url":"/recetas/crema-de-camarones/paso-04.webp","image_alt":"Creamy Shrimp Soup: Add the shrimp"},{"title":"Blend","content":"Take the pot off the heat and blend with an immersion blender until smooth.","image_url":"/recetas/crema-de-camarones/paso-05.webp","image_alt":"Creamy Shrimp Soup: Blend"},{"title":"Add the cream","content":"Return the pot to low heat, add 100 ml cream and warm for 2 minutes, without letting it boil.","image_url":"/recetas/crema-de-camarones/paso-06.webp","image_alt":"Creamy Shrimp Soup: Add the cream"},{"title":"Adjust the seasoning","content":"Taste and adjust with 1 pinch salt and 1 pinch pepper.","image_url":"/recetas/crema-de-camarones/paso-07.webp","image_alt":"Creamy Shrimp Soup: Adjust the seasoning"},{"title":"Sauté and serve","content":"Sauté the remaining 200 g shrimp in 1 tablespoon oil for 2 minutes. Ladle the soup into bowls, top with the sautéed shrimp, sprinkle with parsley and finish with a drizzle of cream.","image_url":"/recetas/crema-de-camarones/paso-08.webp","image_alt":"Creamy Shrimp Soup: Sauté and serve"}],"image_url":"/recetas/crema-de-camarones/portada.webp","gallery":[{"url":"/recetas/crema-de-camarones/portada.webp","alt":"Creamy Shrimp Soup"}],"notes":"Blend carefully: hot liquid splashes, so fill a jug blender no more than halfway. If the soup is too thick, thin it with a little more hot stock. Do not let it boil after adding the cream, or it may split. The shrimp need only a few minutes; overcooking makes them rubbery. It keeps up to 2 days in the fridge; reheat over low heat without boiling and sauté fresh shrimp just before serving.","nutrition":{"calories":360,"protein_g":29.0,"carbs_g":16,"fat_g":20.9,"sodium_mg":912,"serving_size":"1 serving (1/4 of the recipe)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Nutrients per 100 g multiplied by the weights of the ingredients and divided by 4 servings. It uses 500 g raw peeled shrimp, 110 g onion, 6 g garlic, 80 g carrot, 200 g potato, 30 g butter, 16 g tomato paste, 800 g stock, 114 g cream, 13.5 g olive oil and 4 g parsley. Salt and pepper are not counted.","note":"Estimate per serving. The stock is calculated as ready-to-serve chicken broth, and sodium varies widely by brand. All the butter and oil are counted even if some stays in the pot or pan."},"seo":{"title":"Creamy Shrimp Soup, Easy and Rich | Manual de Cocina","description":"Creamy shrimp soup with potato, carrot and cream, topped with sautéed shrimp. Serves 4, ready in 45 minutes. Step-by-step recipe.","image_variants":["/recetas/crema-de-camarones/portada-1x1.webp","/recetas/crema-de-camarones/portada-4x3.webp","/recetas/crema-de-camarones/portada-16x9.webp"],"faq":[{"q":"Can you make shrimp soup without cream?","a":"Yes. It will be lighter: the blended potato already gives body, or you can swap the cream for evaporated milk."},{"q":"Can you use frozen shrimp?","a":"Yes. Thaw them in the fridge, drain them and pat dry with paper towels before adding them to the soup or sautéing."},{"q":"How do I keep the soup from splitting?","a":"Add the cream over low heat and do not let it boil afterwards; just warm it for 2 minutes."}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"55a81ec8-017f-5db8-8725-388a3a4629d0","recipe_group_id":"2b9ed02a-dbdc-4ad6-989e-428323d1bf14","language":"fr","slug":"veloute-de-crevettes","public_path":"/fr/veloute-de-crevettes","source_url":null,"title":"Velouté de crevettes","excerpt":"Velouté de crevettes aux légumes, pomme de terre et crème, couronné de crevettes sautées. Pour 4 personnes, prêt en 45 minutes.","summary":"Le velouté de crevettes se prépare en faisant revenir oignon, ail et carotte au beurre, en cuisant la pomme de terre dans le bouillon avec un peu de concentré de tomate, en ajoutant les crevettes puis en mixant le tout jusqu'à obtenir une texture lisse, que l'on termine avec de la crème. Il se sert avec des crevettes sautées par-dessus.\n\nLa recette demande 45 minutes entre préparation et cuisson. Pour 4 portions.","category":"Soupes et crèmes","difficulty":"Moyenne","course":"Entrée","cuisine":"Latino-américaine","prep_time_minutes":15,"cook_time_minutes":30,"total_time_minutes":45,"servings":4,"keywords":["velouté de crevettes","recette velouté de crevettes","comment faire un velouté de crevettes","soupe de crevettes crémeuse","velouté de crevettes à la pomme de terre","soupe de fruits de mer facile","crema de camarones"],"ingredients":[{"name":"crevettes décortiquées crues","amount":"300","unit":"g","group":"Pour le velouté"},{"name":"oignon","amount":"1","unit":"","group":"Pour le velouté"},{"name":"gousses d'ail","amount":"2","unit":"","group":"Pour le velouté"},{"name":"carotte","amount":"1","unit":"","group":"Pour le velouté"},{"name":"pomme de terre","amount":"1","unit":"","group":"Pour le velouté"},{"name":"beurre","amount":"30","unit":"g","group":"Pour le velouté"},{"name":"concentré de tomate","amount":"1","unit":"cuillère à soupe","group":"Pour le velouté"},{"name":"bouillon de poulet ou de poisson","amount":"800","unit":"ml","group":"Pour le velouté"},{"name":"crème liquide","amount":"100","unit":"ml","group":"Pour le velouté"},{"name":"sel","amount":"1","unit":"pincée","group":"Pour le velouté"},{"name":"poivre noir moulu","amount":"1","unit":"pincée","group":"Pour le velouté"},{"name":"crevettes décortiquées crues, pour sauter","amount":"200","unit":"g","group":"Pour les crevettes sautées"},{"name":"huile d'olive","amount":"1","unit":"cuillère à soupe","group":"Pour les crevettes sautées"},{"name":"persil haché","amount":"1","unit":"cuillère à soupe","group":"Pour servir"},{"name":"crème liquide, pour décorer","amount":"1","unit":"cuillère à soupe","group":"Pour servir"}],"steps":[{"title":"Préparer les ingrédients","content":"Hacher 1 oignon et 2 gousses d'ail, couper 1 carotte en rondelles et 1 pomme de terre épluchée en dés. Répartir les crevettes décortiquées : 300 g pour le velouté et 200 g à faire sauter à la fin.","image_url":"/recetas/crema-de-camarones/paso-01.webp","image_alt":"Velouté de crevettes: Préparer les ingrédients"},{"title":"Faire revenir les légumes","content":"Faire fondre 30 g de beurre dans une marmite à feu moyen et faire revenir l'oignon, l'ail et la carotte 5 minutes, jusqu'à ce qu'ils soient tendres.","image_url":"/recetas/crema-de-camarones/paso-02.webp","image_alt":"Velouté de crevettes: Faire revenir les légumes"},{"title":"Cuire la pomme de terre","content":"Ajouter la pomme de terre, 1 cuillère à soupe de concentré de tomate et 800 ml de bouillon. Cuire 15 minutes à feu moyen, jusqu'à ce que la pomme de terre soit tendre.","image_url":"/recetas/crema-de-camarones/paso-03.webp","image_alt":"Velouté de crevettes: Cuire la pomme de terre"},{"title":"Ajouter les crevettes","content":"Incorporer 300 g de crevettes et cuire 3 minutes, jusqu'à ce qu'elles soient roses.","image_url":"/recetas/crema-de-camarones/paso-04.webp","image_alt":"Velouté de crevettes: Ajouter les crevettes"},{"title":"Mixer","content":"Retirer la marmite du feu et mixer avec un mixeur plongeant jusqu'à obtenir un velouté lisse.","image_url":"/recetas/crema-de-camarones/paso-05.webp","image_alt":"Velouté de crevettes: Mixer"},{"title":"Ajouter la crème","content":"Remettre la marmite à feu doux, ajouter 100 ml de crème liquide et chauffer 2 minutes, sans laisser bouillir.","image_url":"/recetas/crema-de-camarones/paso-06.webp","image_alt":"Velouté de crevettes: Ajouter la crème"},{"title":"Rectifier l'assaisonnement","content":"Goûter et rectifier avec 1 pincée de sel et 1 pincée de poivre.","image_url":"/recetas/crema-de-camarones/paso-07.webp","image_alt":"Velouté de crevettes: Rectifier l'assaisonnement"},{"title":"Faire sauter et servir","content":"Faire sauter les 200 g de crevettes restantes 2 minutes dans 1 cuillère à soupe d'huile. Verser le velouté dans des assiettes creuses, répartir les crevettes sautées dessus, parsemer de persil et terminer par un filet de crème.","image_url":"/recetas/crema-de-camarones/paso-08.webp","image_alt":"Velouté de crevettes: Faire sauter et servir"}],"image_url":"/recetas/crema-de-camarones/portada.webp","gallery":[{"url":"/recetas/crema-de-camarones/portada.webp","alt":"Velouté de crevettes"}],"notes":"Mixez avec précaution : le liquide chaud éclabousse, ne remplissez donc pas un blender à plus de la moitié. Si le velouté est trop épais, allongez-le avec un peu de bouillon chaud. Ne le laissez pas bouillir après avoir ajouté la crème, sinon elle risque de trancher. Les crevettes ne demandent que quelques minutes : trop cuites, elles deviennent caoutchouteuses. Il se conserve 2 jours au réfrigérateur ; réchauffez-le à feu doux sans faire bouillir et faites sauter des crevettes fraîches au dernier moment.","nutrition":{"calories":360,"protein_g":29.0,"carbs_g":16,"fat_g":20.9,"sodium_mg":912,"serving_size":"1 portion (1/4 de la recette)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Somme des nutriments pour 100 g multipliés par le poids des ingrédients et divisés par 4 portions. On utilise 500 g de crevettes crues décortiquées, 110 g d'oignon, 6 g d'ail, 80 g de carotte, 200 g de pomme de terre, 30 g de beurre, 16 g de concentré de tomate, 800 g de bouillon, 114 g de crème, 13,5 g d'huile d'olive et 4 g de persil. Le sel et le poivre ne sont pas comptés.","note":"Estimation par portion. Le bouillon est calculé comme un bouillon de poulet prêt à consommer, et le sodium varie beaucoup selon la marque. Tout le beurre et toute l'huile sont comptés même si une partie reste dans la marmite ou la poêle."},"seo":{"title":"Velouté de crevettes, crémeux et facile | Manual de Cocina","description":"Velouté de crevettes à la pomme de terre, carotte et crème, couronné de crevettes sautées. Pour 4 personnes, prêt en 45 minutes. Recette pas à pas.","image_variants":["/recetas/crema-de-camarones/portada-1x1.webp","/recetas/crema-de-camarones/portada-4x3.webp","/recetas/crema-de-camarones/portada-16x9.webp"],"faq":[{"q":"Peut-on faire le velouté de crevettes sans crème ?","a":"Oui. Il sera plus léger : la pomme de terre mixée donne déjà du corps, ou l'on peut remplacer la crème par du lait évaporé."},{"q":"Peut-on utiliser des crevettes surgelées ?","a":"Oui. Les décongeler au réfrigérateur, les égoutter et les éponger avec du papier absorbant avant de les ajouter au velouté ou de les faire sauter."},{"q":"Comment éviter que le velouté ne tranche ?","a":"Ajouter la crème à feu doux et ne plus laisser bouillir ensuite ; la chauffer seulement 2 minutes."}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"7e69fac6-c1a8-574e-a3b4-4c7864eefa40","recipe_group_id":"2b9ed02a-dbdc-4ad6-989e-428323d1bf14","language":"it","slug":"crema-di-gamberetti","public_path":"/it/crema-di-gamberetti","source_url":null,"title":"Crema di gamberetti","excerpt":"Crema di gamberetti con verdure, patata e panna, completata da gamberetti saltati. Per 4 persone, pronta in 45 minuti.","summary":"La crema di gamberetti si prepara soffriggendo cipolla, aglio e carota nel burro, cuocendo la patata nel brodo con un po' di concentrato di pomodoro, aggiungendo i gamberetti e frullando tutto fino a ottenere una crema liscia, che si completa con la panna. Si serve con gamberetti saltati sopra.\n\nLa ricetta richiede 45 minuti tra preparazione e cottura. Per 4 porzioni.","category":"Zuppe e creme","difficulty":"Media","course":"Antipasto","cuisine":"Latinoamericana","prep_time_minutes":15,"cook_time_minutes":30,"total_time_minutes":45,"servings":4,"keywords":["crema di gamberetti","ricetta crema di gamberetti","come fare la crema di gamberetti","zuppa di gamberetti cremosa","crema di gamberetti con patate","zuppa di pesce facile","crema de camarones"],"ingredients":[{"name":"gamberetti sgusciati crudi","amount":"300","unit":"g","group":"Per la crema"},{"name":"cipolla","amount":"1","unit":"","group":"Per la crema"},{"name":"spicchi d'aglio","amount":"2","unit":"","group":"Per la crema"},{"name":"carota","amount":"1","unit":"","group":"Per la crema"},{"name":"patata","amount":"1","unit":"","group":"Per la crema"},{"name":"burro","amount":"30","unit":"g","group":"Per la crema"},{"name":"concentrato di pomodoro","amount":"1","unit":"cucchiaio","group":"Per la crema"},{"name":"brodo di pollo o di pesce","amount":"800","unit":"ml","group":"Per la crema"},{"name":"panna","amount":"100","unit":"ml","group":"Per la crema"},{"name":"sale","amount":"1","unit":"pizzico","group":"Per la crema"},{"name":"pepe nero macinato","amount":"1","unit":"pizzico","group":"Per la crema"},{"name":"gamberetti sgusciati crudi, per saltare","amount":"200","unit":"g","group":"Per i gamberetti saltati"},{"name":"olio d'oliva","amount":"1","unit":"cucchiaio","group":"Per i gamberetti saltati"},{"name":"prezzemolo tritato","amount":"1","unit":"cucchiaio","group":"Per servire"},{"name":"panna, per decorare","amount":"1","unit":"cucchiaio","group":"Per servire"}],"steps":[{"title":"Prepara gli ingredienti","content":"Trita 1 cipolla e 2 spicchi d'aglio, taglia a rondelle 1 carota e a cubetti 1 patata sbucciata. Dividi i gamberetti sgusciati: 300 g per la crema e 200 g da saltare alla fine.","image_url":"/recetas/crema-de-camarones/paso-01.webp","image_alt":"Crema di gamberetti: Prepara gli ingredienti"},{"title":"Soffriggi le verdure","content":"Sciogli 30 g di burro in una pentola a fuoco medio e fai soffriggere la cipolla, l'aglio e la carota per 5 minuti, finché sono morbidi.","image_url":"/recetas/crema-de-camarones/paso-02.webp","image_alt":"Crema di gamberetti: Soffriggi le verdure"},{"title":"Cuoci la patata","content":"Aggiungi la patata, 1 cucchiaio di concentrato di pomodoro e 800 ml di brodo. Cuoci per 15 minuti a fuoco medio, finché la patata è tenera.","image_url":"/recetas/crema-de-camarones/paso-03.webp","image_alt":"Crema di gamberetti: Cuoci la patata"},{"title":"Aggiungi i gamberetti","content":"Unisci 300 g di gamberetti e cuoci per 3 minuti, finché sono rosa.","image_url":"/recetas/crema-de-camarones/paso-04.webp","image_alt":"Crema di gamberetti: Aggiungi i gamberetti"},{"title":"Frulla","content":"Togli la pentola dal fuoco e frulla con un frullatore a immersione fino a ottenere una crema liscia.","image_url":"/recetas/crema-de-camarones/paso-05.webp","image_alt":"Crema di gamberetti: Frulla"},{"title":"Aggiungi la panna","content":"Rimetti la pentola a fuoco basso, aggiungi 100 ml di panna e scalda per 2 minuti, senza far bollire.","image_url":"/recetas/crema-de-camarones/paso-06.webp","image_alt":"Crema di gamberetti: Aggiungi la panna"},{"title":"Aggiusta di sapore","content":"Assaggia e aggiusta con 1 pizzico di sale e 1 pizzico di pepe.","image_url":"/recetas/crema-de-camarones/paso-07.webp","image_alt":"Crema di gamberetti: Aggiusta di sapore"},{"title":"Salta e servi","content":"Salta i restanti 200 g di gamberetti per 2 minuti con 1 cucchiaio di olio. Versa la crema nei piatti fondi, distribuisci sopra i gamberetti saltati, spolvera con il prezzemolo e completa con un filo di panna.","image_url":"/recetas/crema-de-camarones/paso-08.webp","image_alt":"Crema di gamberetti: Salta e servi"}],"image_url":"/recetas/crema-de-camarones/portada.webp","gallery":[{"url":"/recetas/crema-de-camarones/portada.webp","alt":"Crema di gamberetti"}],"notes":"Frulla con attenzione: il liquido caldo schizza, quindi se usi un frullatore a bicchiere non riempirlo oltre la metà. Se la crema è troppo densa, allungala con un po' di brodo caldo. Non farla bollire dopo aver aggiunto la panna, o potrebbe separarsi. I gamberetti richiedono pochi minuti: se cuociono troppo diventano gommosi. Si conserva fino a 2 giorni in frigorifero; riscaldala a fuoco basso senza far bollire e salta i gamberetti freschi al momento.","nutrition":{"calories":360,"protein_g":29.0,"carbs_g":16,"fat_g":20.9,"sodium_mg":912,"serving_size":"1 porzione (1/4 della ricetta)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Somma dei nutrienti per 100 g moltiplicati per i pesi degli ingredienti e divisi per 4 porzioni. Si usano 500 g di gamberetti crudi sgusciati, 110 g di cipolla, 6 g di aglio, 80 g di carota, 200 g di patata, 30 g di burro, 16 g di concentrato di pomodoro, 800 g di brodo, 114 g di panna, 13,5 g di olio d'oliva e 4 g di prezzemolo. Sale e pepe non sono conteggiati.","note":"Stima per porzione. Il brodo è calcolato come brodo di pollo pronto, e il sodio varia molto a seconda della marca. Si conta tutto il burro e tutto l'olio anche se una parte resta nella pentola o nella padella."},"seo":{"title":"Crema di gamberetti, cremosa e facile | Manual de Cocina","description":"Crema di gamberetti con patata, carota e panna, completata da gamberetti saltati. Per 4 persone, pronta in 45 minuti. Ricetta passo dopo passo.","image_variants":["/recetas/crema-de-camarones/portada-1x1.webp","/recetas/crema-de-camarones/portada-4x3.webp","/recetas/crema-de-camarones/portada-16x9.webp"],"faq":[{"q":"Si può fare la crema di gamberetti senza panna?","a":"Sì. Sarà più leggera: la patata frullata dà già corpo, oppure si può sostituire la panna con latte evaporato."},{"q":"Si possono usare gamberetti surgelati?","a":"Sì. Scongelali in frigorifero, scolali e asciugali con carta da cucina prima di aggiungerli alla crema o di saltarli."},{"q":"Come evito che la crema si separi?","a":"Aggiungi la panna a fuoco basso e non farla più bollire; scaldala solo per 2 minuti."}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"39412903-9c60-50b3-bd6c-7b8da540498a","recipe_group_id":"2b9ed02a-dbdc-4ad6-989e-428323d1bf14","language":"ja","slug":"エビのポタージュ","public_path":"/ja/エビのポタージュ","source_url":null,"title":"エビのポタージュ","excerpt":"野菜とじゃがいも、生クリームで作るなめらかなエビのポタージュに、ソテーしたエビをのせて。4人分、45分で完成。","summary":"エビのポタージュは、玉ねぎ、にんにく、にんじんをバターで炒め、じゃがいもをトマトペーストを少し加えたスープで煮て、エビを加えてなめらかになるまで攪拌し、生クリームで仕上げて作ります。ソテーしたエビを上にのせて供します。\n\n下ごしらえから調理まで45分かかります。4人分です。","category":"スープ・ポタージュ","difficulty":"普通","course":"前菜","cuisine":"ラテンアメリカ料理","prep_time_minutes":15,"cook_time_minutes":30,"total_time_minutes":45,"servings":4,"keywords":["エビのポタージュ","エビ ポタージュ レシピ","エビ スープ 作り方","エビ クリームスープ","エビとじゃがいものスープ","魚介スープ 簡単","クレマ・デ・カマロネス"],"ingredients":[{"name":"殻をむいた生のエビ","amount":"300","unit":"g","group":"ポタージュ用"},{"name":"玉ねぎ","amount":"1","unit":"","group":"ポタージュ用"},{"name":"にんにく","amount":"2","unit":"","group":"ポタージュ用"},{"name":"にんじん","amount":"1","unit":"","group":"ポタージュ用"},{"name":"じゃがいも","amount":"1","unit":"","group":"ポタージュ用"},{"name":"バター","amount":"30","unit":"g","group":"ポタージュ用"},{"name":"トマトペースト","amount":"1","unit":"大さじ","group":"ポタージュ用"},{"name":"鶏または魚のスープ（ブイヨン）","amount":"800","unit":"ml","group":"ポタージュ用"},{"name":"生クリーム","amount":"100","unit":"ml","group":"ポタージュ用"},{"name":"塩","amount":"1","unit":"ひとつまみ","group":"ポタージュ用"},{"name":"黒こしょう（挽いたもの）","amount":"1","unit":"ひとつまみ","group":"ポタージュ用"},{"name":"殻をむいた生のエビ（ソテー用）","amount":"200","unit":"g","group":"ソテーするエビ用"},{"name":"オリーブオイル","amount":"1","unit":"大さじ","group":"ソテーするエビ用"},{"name":"パセリ（みじん切り）","amount":"1","unit":"大さじ","group":"仕上げ用"},{"name":"生クリーム（仕上げ用）","amount":"1","unit":"大さじ","group":"仕上げ用"}],"steps":[{"title":"材料を準備する","content":"玉ねぎ1個とにんにく2片をみじん切りに、にんじん1本を薄切りに、皮をむいたじゃがいも1個をさいの目に切ります。殻をむいたエビは、ポタージュ用に300g、最後にソテーする用に200gに分けます。","image_url":"/recetas/crema-de-camarones/paso-01.webp","image_alt":"エビのポタージュ: 材料を準備する"},{"title":"野菜を炒める","content":"鍋にバター30gを中火で溶かし、玉ねぎ、にんにく、にんじんをやわらかくなるまで5分炒めます。","image_url":"/recetas/crema-de-camarones/paso-02.webp","image_alt":"エビのポタージュ: 野菜を炒める"},{"title":"じゃがいもを煮る","content":"じゃがいも、トマトペースト大さじ1、スープ800mlを加え、中火でじゃがいもがやわらかくなるまで15分煮ます。","image_url":"/recetas/crema-de-camarones/paso-03.webp","image_alt":"エビのポタージュ: じゃがいもを煮る"},{"title":"エビを加える","content":"エビ300gを加え、色が変わるまで3分煮ます。","image_url":"/recetas/crema-de-camarones/paso-04.webp","image_alt":"エビのポタージュ: エビを加える"},{"title":"攪拌する","content":"鍋を火からおろし、ハンドブレンダーでなめらかになるまで攪拌します。","image_url":"/recetas/crema-de-camarones/paso-05.webp","image_alt":"エビのポタージュ: 攪拌する"},{"title":"生クリームを加える","content":"鍋を弱火に戻し、生クリーム100mlを加えて、沸騰させないように2分温めます。","image_url":"/recetas/crema-de-camarones/paso-06.webp","image_alt":"エビのポタージュ: 生クリームを加える"},{"title":"味をととのえる","content":"味見をして、塩ひとつまみとこしょうひとつまみで味をととのえます。","image_url":"/recetas/crema-de-camarones/paso-07.webp","image_alt":"エビのポタージュ: 味をととのえる"},{"title":"ソテーして盛り付ける","content":"残りのエビ200gをオイル大さじ1で2分炒めます。ポタージュを深めの器に注ぎ、ソテーしたエビをのせ、パセリをふり、生クリームをひと回しかけて仕上げます。","image_url":"/recetas/crema-de-camarones/paso-08.webp","image_alt":"エビのポタージュ: ソテーして盛り付ける"}],"image_url":"/recetas/crema-de-camarones/portada.webp","gallery":[{"url":"/recetas/crema-de-camarones/portada.webp","alt":"エビのポタージュ"}],"notes":"攪拌するときは気をつけてください。熱い液体は飛び散るので、ミキサーを使う場合は容器の半分以上入れないでください。濃すぎる場合は、温めたスープを少し足してのばします。生クリームを加えたあとは沸騰させないでください。分離することがあります。エビは数分で火が通ります。加熱しすぎるとかたくなります。冷蔵庫で2日間保存でき、弱火で沸騰させないように温め直し、エビは食べる直前に焼き直してください。","nutrition":{"calories":360,"protein_g":29.0,"carbs_g":16,"fat_g":20.9,"sodium_mg":912,"serving_size":"1人分（レシピの1/4）","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"100gあたりの栄養素に材料の重量を掛け、4人分で割って合計しています。生のむきエビ500g、玉ねぎ110g、にんにく6g、にんじん80g、じゃがいも200g、バター30g、トマトペースト16g、スープ800g、生クリーム114g、オリーブオイル13.5g、パセリ4gを使用しています。塩とこしょうは計算に含めていません。","note":"1人分の目安です。スープは市販の鶏ガラスープ（そのまま飲めるタイプ）として計算しており、ナトリウム量は商品によって大きく異なります。バターとオイルは鍋やフライパンに残る分も含めて全量を計算しています。"},"seo":{"title":"エビのポタージュの作り方｜なめらかで簡単 | Manual de Cocina","description":"じゃがいも、にんじん、生クリームで作るなめらかなエビのポタージュ。ソテーしたエビをのせて、4人分、45分で完成。手順を写真付きで解説します。","image_variants":["/recetas/crema-de-camarones/portada-1x1.webp","/recetas/crema-de-camarones/portada-4x3.webp","/recetas/crema-de-camarones/portada-16x9.webp"],"faq":[{"q":"生クリームなしでエビのポタージュは作れますか？","a":"作れます。軽い仕上がりになります。攪拌したじゃがいもでもとろみがつきますし、生クリームをエバミルクに替えることもできます。"},{"q":"冷凍のエビでも作れますか？","a":"作れます。冷蔵庫で解凍し、水気をきって、スープに加える前やソテーする前にキッチンペーパーでふき取ります。"},{"q":"ポタージュが分離しないようにするには？","a":"生クリームは弱火で加え、そのあとは沸騰させないようにします。2分温めるだけにしてください。"}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"9c5b1ec5-060b-540a-a23d-911865473180","recipe_group_id":"2b9ed02a-dbdc-4ad6-989e-428323d1bf14","language":"pt","slug":"creme-de-camarao","public_path":"/pt/creme-de-camarao","source_url":null,"title":"Creme de camarão","excerpt":"Creme de camarão com legumes, batata e creme de leite, coroado com camarões salteados. Para 4 pessoas, pronto em 45 minutos.","summary":"O creme de camarão é feito refogando cebola, alho e cenoura na manteiga, cozinhando a batata no caldo com um pouco de extrato de tomate, juntando os camarões e batendo tudo até ficar liso, finalizando com creme de leite. É servido com camarões salteados por cima.\n\nA receita leva 45 minutos entre preparo e cozimento. Rende 4 porções.","category":"Sopas e cremes","difficulty":"Média","course":"Entrada","cuisine":"Latino-americana","prep_time_minutes":15,"cook_time_minutes":30,"total_time_minutes":45,"servings":4,"keywords":["creme de camarão","receita de creme de camarão","como fazer creme de camarão","sopa cremosa de camarão","creme de camarão com batata","sopa de frutos do mar fácil","crema de camarones"],"ingredients":[{"name":"camarões descascados crus","amount":"300","unit":"g","group":"Para o creme"},{"name":"cebola","amount":"1","unit":"","group":"Para o creme"},{"name":"dentes de alho","amount":"2","unit":"","group":"Para o creme"},{"name":"cenoura","amount":"1","unit":"","group":"Para o creme"},{"name":"batata","amount":"1","unit":"","group":"Para o creme"},{"name":"manteiga","amount":"30","unit":"g","group":"Para o creme"},{"name":"extrato de tomate","amount":"1","unit":"colher de sopa","group":"Para o creme"},{"name":"caldo de galinha ou de peixe","amount":"800","unit":"ml","group":"Para o creme"},{"name":"creme de leite","amount":"100","unit":"ml","group":"Para o creme"},{"name":"sal","amount":"1","unit":"pitada","group":"Para o creme"},{"name":"pimenta-do-reino moída","amount":"1","unit":"pitada","group":"Para o creme"},{"name":"camarões descascados crus, para saltear","amount":"200","unit":"g","group":"Para os camarões salteados"},{"name":"azeite","amount":"1","unit":"colher de sopa","group":"Para os camarões salteados"},{"name":"salsinha picada","amount":"1","unit":"colher de sopa","group":"Para servir"},{"name":"creme de leite, para decorar","amount":"1","unit":"colher de sopa","group":"Para servir"}],"steps":[{"title":"Prepare os ingredientes","content":"Pique 1 cebola e 2 dentes de alho, corte 1 cenoura em rodelas e 1 batata descascada em cubos. Separe os camarões descascados: 300 g para o creme e 200 g para saltear no final.","image_url":"/recetas/crema-de-camarones/paso-01.webp","image_alt":"Creme de camarão: Prepare os ingredientes"},{"title":"Refogue os legumes","content":"Derreta 30 g de manteiga em uma panela em fogo médio e refogue a cebola, o alho e a cenoura por 5 minutos, até ficarem macios.","image_url":"/recetas/crema-de-camarones/paso-02.webp","image_alt":"Creme de camarão: Refogue os legumes"},{"title":"Cozinhe a batata","content":"Junte a batata, 1 colher de sopa de extrato de tomate e 800 ml de caldo. Cozinhe por 15 minutos em fogo médio, até a batata ficar macia.","image_url":"/recetas/crema-de-camarones/paso-03.webp","image_alt":"Creme de camarão: Cozinhe a batata"},{"title":"Junte os camarões","content":"Adicione 300 g de camarões e cozinhe por 3 minutos, até ficarem rosados.","image_url":"/recetas/crema-de-camarones/paso-04.webp","image_alt":"Creme de camarão: Junte os camarões"},{"title":"Bata","content":"Retire a panela do fogo e bata com um mixer de mão até obter um creme liso.","image_url":"/recetas/crema-de-camarones/paso-05.webp","image_alt":"Creme de camarão: Bata"},{"title":"Junte o creme de leite","content":"Volte a panela ao fogo baixo, adicione 100 ml de creme de leite e aqueça por 2 minutos, sem deixar ferver.","image_url":"/recetas/crema-de-camarones/paso-06.webp","image_alt":"Creme de camarão: Junte o creme de leite"},{"title":"Ajuste o tempero","content":"Prove e ajuste com 1 pitada de sal e 1 pitada de pimenta.","image_url":"/recetas/crema-de-camarones/paso-07.webp","image_alt":"Creme de camarão: Ajuste o tempero"},{"title":"Salteie e sirva","content":"Salteie os 200 g de camarões restantes por 2 minutos com 1 colher de sopa de azeite. Sirva o creme em pratos fundos, distribua os camarões salteados por cima, polvilhe salsinha e finalize com um fio de creme de leite.","image_url":"/recetas/crema-de-camarones/paso-08.webp","image_alt":"Creme de camarão: Salteie e sirva"}],"image_url":"/recetas/crema-de-camarones/portada.webp","gallery":[{"url":"/recetas/crema-de-camarones/portada.webp","alt":"Creme de camarão"}],"notes":"Bata com cuidado: o líquido quente espirra, por isso não encha o copo do liquidificador mais da metade. Se o creme ficar muito grosso, afine com um pouco mais de caldo quente. Não deixe ferver depois de juntar o creme de leite, ou ele pode talhar. Os camarões precisam de poucos minutos: se passarem do ponto, ficam borrachudos. Conserva-se até 2 dias na geladeira; reaqueça em fogo baixo, sem ferver, e salteie camarões frescos na hora.","nutrition":{"calories":360,"protein_g":29.0,"carbs_g":16,"fat_g":20.9,"sodium_mg":912,"serving_size":"1 porção (1/4 da receita)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Soma dos nutrientes por 100 g multiplicados pelo peso dos ingredientes e divididos por 4 porções. Usam-se 500 g de camarões crus descascados, 110 g de cebola, 6 g de alho, 80 g de cenoura, 200 g de batata, 30 g de manteiga, 16 g de extrato de tomate, 800 g de caldo, 114 g de creme de leite, 13,5 g de azeite e 4 g de salsinha. Sal e pimenta-do-reino não são contados.","note":"Estimativa por porção. O caldo é calculado como caldo de galinha pronto para consumo, e o sódio varia muito conforme a marca. Toda a manteiga e todo o azeite são contados, mesmo que parte fique na panela ou na frigideira."},"seo":{"title":"Creme de camarão cremoso e fácil | Manual de Cocina","description":"Creme de camarão com batata, cenoura e creme de leite, coroado com camarões salteados. Para 4 pessoas, pronto em 45 minutos. Receita passo a passo.","image_variants":["/recetas/crema-de-camarones/portada-1x1.webp","/recetas/crema-de-camarones/portada-4x3.webp","/recetas/crema-de-camarones/portada-16x9.webp"],"faq":[{"q":"Dá para fazer creme de camarão sem creme de leite?","a":"Dá. Fica mais leve: a batata batida já dá corpo, ou você pode trocar o creme de leite por leite evaporado."},{"q":"Posso usar camarão congelado?","a":"Pode. Descongele na geladeira, escorra e seque com papel-toalha antes de juntar ao creme ou saltear."},{"q":"Como evitar que o creme talhe?","a":"Junte o creme de leite em fogo baixo e não deixe ferver depois; apenas aqueça por 2 minutos."}]},"published":true,"editorial_status":"published","content_html":""}
]$j$::jsonb;
  ts constant timestamptz := now();
  n int;
begin
  if (select count(*) from public.recipes where recipe_group_id = g) <> 1
     or not exists (select 1 from public.recipes where id = es_id and language = 'es' and published = false and public_path = '/receta-crema-de-camarones') then
    raise exception 'Estado previo inesperado del grupo';
  end if;
  if exists (select 1 from public.recipes where id <> es_id and (public_path = any (select x->>'public_path' from jsonb_array_elements(j) x)
      or (language, slug) in (select x->>'language', x->>'slug' from jsonb_array_elements(j) x))) then
    raise exception 'Colisión de slug/public_path';
  end if;
  if exists (select 1 from public.content_pages where public_path = any (select x->>'public_path' from jsonb_array_elements(j) x)) then
    raise exception 'Colisión con content_pages';
  end if;

  update public.recipes r set
    title = x.title, excerpt = x.excerpt, summary = x.summary, ingredients = x.ingredients, steps = x.steps,
    category = x.category, prep_time_minutes = x.prep_time_minutes, cook_time_minutes = x.cook_time_minutes,
    total_time_minutes = x.total_time_minutes, servings = x.servings, image_url = x.image_url,
    content_html = x.content_html, notes = x.notes, difficulty = x.difficulty, course = x.course,
    cuisine = x.cuisine, keywords = x.keywords, nutrition = x.nutrition, gallery = x.gallery, seo = x.seo,
    editorial_status = 'published', ready_at = ts, published = true
  from jsonb_populate_recordset(null::public.recipes, j) x
  where r.id = es_id and x.language = 'es';
  get diagnostics n = row_count;
  if n <> 1 then raise exception 'UPDATE ES afectó % filas', n; end if;

  insert into public.recipes (id, recipe_group_id, language, slug, public_path, source_url, title, excerpt, summary,
    ingredients, steps, category, prep_time_minutes, cook_time_minutes, total_time_minutes, servings, image_url,
    content_html, notes, difficulty, course, cuisine, keywords, nutrition, gallery, seo, editorial_status, ready_at, published)
  select x.id, g, x.language, x.slug, x.public_path, null, x.title, x.excerpt, x.summary,
    x.ingredients, x.steps, x.category, x.prep_time_minutes, x.cook_time_minutes, x.total_time_minutes, x.servings, x.image_url,
    '', x.notes, x.difficulty, x.course, x.cuisine, x.keywords,
    x.nutrition || jsonb_build_object('inputs', (select nutrition->'inputs' from public.recipes where id = es_id)),
    x.gallery, x.seo, 'published', ts, true
  from jsonb_populate_recordset(null::public.recipes, j) x
  where x.language <> 'es';
  get diagnostics n = row_count;
  if n <> 6 then raise exception 'INSERT afectó % filas', n; end if;

  if (select count(*) from public.recipes where recipe_group_id = g and published and editorial_status = 'published'
        and language in ('es','de','en','fr','it','ja','pt')) <> 7 then
    raise exception 'El grupo no quedó con 7 filas publicadas';
  end if;
end
$pub$;
